"""Converts time float to tuple

    Args:
        duration (float): converts duration to a tuple
    Returns:
        tuple: Duration split into hours, minutes, and seconds
    """
def timeToTuple(duration: Any) -> object {
    (hours, rem) = divmod(duration, 3600);
    (minutes, rem2) = divmod(rem, 60);
    (seconds, mseconds) = divmod(rem2, 1);
    return (int(hours), int(minutes), int(seconds), round((mseconds * 1000)));
}

"""Takes float inches and converts to human height in ft/inches"""
def height_human(float_inches: Any) -> object {
    feet = int(round((float_inches / 12), 2));
    inches_left = round((float_inches - (feet * 12)));
    result = f"{feet} foot, {inches_left} inches";
    return result;
}

